def contains(big,small):
    H,W=len(big),len(big[0]); h,w=len(small),len(small[0])
    for r in range(H-h+1):
        for c in range(W-w+1):
            if all(big[r+i][c+j]==small[i][j] for i in range(h) for j in range(w)): return True
